import { expect, test } from '@playwright/test';

/**
 * COMMUNITY-ACCESS-001 in a real browser, against the real published application, its real
 * session cookie and a real PostgreSQL behind it.
 *
 * The setup token is generated by scripts/e2e.sh for this run and handed to the fixtures through
 * the environment. It is never written into this file, never printed and never asserted on: the
 * fixtures only ever observe what the browser and the server expose.
 */
const ACCESS_TOKEN = process.env.CHRONICLEAF_E2E_ACCESS_TOKEN;

const SESSION_COOKIE = 'chronicleaf_session';

test.beforeEach(async ({ page }) => {
  if (!ACCESS_TOKEN) {
    throw new Error(
      'CHRONICLEAF_E2E_ACCESS_TOKEN is not set. Run these fixtures through scripts/e2e.sh, which ' +
        'starts the published application with a real access token hash and a real database.',
    );
  }

  await page.context().clearCookies();
  await page.goto('/');
});

test('a keyboard-only sign-in opens the owner session', async ({ page }) => {
  await expect(page.getByTestId('session-gate')).toBeVisible();
  await expect(page.getByRole('heading', { name: 'Owner sign-in' })).toBeVisible();

  // The owner never sees a private value while signed out: the gate is a form and nothing more.
  // PRODUCT-SHELL-UX-001 migration (named, in-package): session internals
  // render only under /settings, so no actor testid exists outside it.
  await expect(page.getByTestId('settings-actor')).toHaveCount(0);

  // Keyboard only: focus the labelled field, type the token, submit with Enter.
  await page.getByTestId('session-token-input').focus();
  await expect(page.getByTestId('session-token-input')).toBeFocused();
  await page.keyboard.type(ACCESS_TOKEN as string);
  await page.keyboard.press('Enter');

  await expect(page.getByRole('heading', { name: 'Owner session' })).toBeVisible();

  // A private route now works for this browser, from the page's own session cookie: the request is
  // made by the page itself, so the cookie is the browser's, not a test-supplied header.
  // The owner identity is a stable UUID from the database, not anything the page decided — proven
  // at the API boundary, because the page renders the actor as a label, never as a raw UUID dump.
  const session = await readSessionFromThePage(page);
  expect(session.status).toBe(200);
  const actorId = (session.body as { actorId: string }).actorId;
  expect(actorId).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
  expect(session.body).toEqual({ authenticated: true, actorId });

  // The settings page names the session facts without dumping the raw identity.
  await page.getByTestId('nav-settings').click();
  await expect(page.getByTestId('settings-actor')).toContainText("This installation's owner");
  await expect(page.getByTestId('settings-idle')).toContainText('12 hours');
  await expect(page.getByTestId('settings-lifetime')).toContainText('7 days');
});

test('the session cookie is HttpOnly and SameSite=Strict, and is not readable by script', async ({ page }) => {
  await signInFromTheKeyboard(page);

  const cookies = await page.context().cookies();
  const session = cookies.find((cookie) => cookie.name === SESSION_COOKIE);

  expect(session, 'the sign-in must set a session cookie').toBeTruthy();
  expect(session?.httpOnly).toBe(true);
  expect(session?.sameSite).toBe('Strict');
  expect(session?.path).toBe('/');
  expect(session?.secure).toBe(true);

  // The value is an opaque random token, not the setup token the owner typed.
  expect(session?.value).toMatch(/^[0-9a-f]{64}$/);
  expect(session?.value).not.toBe(ACCESS_TOKEN);

  // And nothing in the page's own JavaScript can read it, because the cookie is HttpOnly.
  const readable = await page.evaluate(() => document.cookie);
  expect(readable).not.toContain(SESSION_COOKIE);
});

test('a private route is refused to a browser with no session', async ({ request }) => {
  const response = await request.get('/api/session', { headers: { Origin: 'https://elsewhere.example' } });

  expect(response.status()).toBe(401);
  expect(await response.json()).toMatchObject({ code: 'unauthenticated' });
  expect(Object.keys(await response.json()).sort()).toEqual(['code', 'message', 'traceId']);
});

test('a wrong token is refused without disclosing what was wrong', async ({ page }) => {
  await page.getByTestId('session-token-input').fill(`${ACCESS_TOKEN}x`);
  await page.getByTestId('session-submit').click();

  const failure = page.getByTestId('session-error');
  await expect(failure).toBeVisible();
  await expect(failure).toContainText('The access token was not accepted.');

  // The generic message, and no session.
  await expect(page.getByRole('heading', { name: 'Owner sign-in' })).toBeVisible();
  expect((await page.context().cookies()).find((cookie) => cookie.name === SESSION_COOKIE)).toBeUndefined();
});

test('signing out revokes the session and the private route is refused again', async ({ page }) => {
  await signInFromTheKeyboard(page);

  const before = await readSessionFromThePage(page);
  expect(before.status).toBe(200);

  // The value the browser is holding, kept so the revocation can be observed afterwards.
  const stale = (await page.context().cookies()).find((cookie) => cookie.name === SESSION_COOKIE);
  expect(stale?.value).toBeTruthy();

  await page.getByTestId('session-sign-out').focus();
  await page.keyboard.press('Enter');

  await expect(page.getByRole('heading', { name: 'Owner sign-in' })).toBeVisible();

  // The browser dropped the cookie.
  expect((await page.context().cookies()).find((cookie) => cookie.name === SESSION_COOKIE)).toBeUndefined();
  expect((await readSessionFromThePage(page)).status).toBe(401);

  // And the session is gone on the server too: presenting the revoked cookie again is refused
  // rather than quietly accepted, which is the difference between revoking and forgetting.
  await page.context().addCookies([
    {
      name: SESSION_COOKIE,
      value: stale!.value,
      domain: '127.0.0.1',
      path: '/',
      httpOnly: true,
      secure: true,
      sameSite: 'Strict',
    },
  ]);

  const revoked = await readSessionFromThePage(page);
  expect(revoked.status).toBe(401);
  expect(revoked.body).toMatchObject({ code: 'unauthenticated' });
});

/**
 * Reads a private route from inside the page, so the request carries the browser's own session
 * cookie exactly as the application would send it.
 */
async function readSessionFromThePage(page: import('@playwright/test').Page) {
  return page.evaluate(async () => {
    const response = await fetch('/api/session', { credentials: 'same-origin' });
    return { status: response.status, body: await response.json() };
  });
}

/** Signs in with the keyboard alone: focus, type, Enter. */
async function signInFromTheKeyboard(page: import('@playwright/test').Page) {
  await page.getByTestId('session-token-input').focus();
  await page.keyboard.type(ACCESS_TOKEN as string);
  await page.keyboard.press('Enter');
  await expect(page.getByRole('heading', { name: 'Owner session' })).toBeVisible();
}
